$ErrorActionPreference='Stop'
$helpers=Get-Content (Join-Path $PSScriptRoot 'windows-smoke.ps1') -Raw
Invoke-Expression $helpers.Substring(0,$helpers.IndexOf('$exe ='))
Add-Type -AssemblyName System.Drawing
Add-Type @'
using System;
using System.Runtime.InteropServices;
public static class InteractiveUI {
 [DllImport("user32.dll")] static extern IntPtr SendMessageTimeout(IntPtr h,uint message,IntPtr wp,IntPtr lp,uint flags,uint ms,out UIntPtr result);
 [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h,int n);
 [DllImport("user32.dll")] static extern IntPtr GetPropA(IntPtr h,string key);
 [DllImport("user32.dll")] static extern bool SetForegroundWindow(IntPtr h);
 [DllImport("user32.dll")] static extern bool ClientToScreen(IntPtr h,ref Point p);
 [DllImport("user32.dll")] static extern bool SetCursorPos(int x,int y);
 [DllImport("user32.dll")] static extern void mouse_event(uint flags,uint x,uint y,uint data,UIntPtr extra);
 [StructLayout(LayoutKind.Sequential)] struct Point {public int x,y;}
 [DllImport("user32.dll")] public static extern IntPtr GetParent(IntPtr h);
 [DllImport("user32.dll",EntryPoint="GetWindowLongW")] public static extern int Style(IntPtr h,int index);
 [DllImport("user32.dll")] public static extern bool MoveWindow(IntPtr h,int x,int y,int w,int height,bool repaint);
 [DllImport("user32.dll")] static extern IntPtr GetDC(IntPtr h);
 [DllImport("user32.dll")] static extern int ReleaseDC(IntPtr h,IntPtr dc);
 [DllImport("gdi32.dll")] static extern IntPtr CreateCompatibleDC(IntPtr dc);
 [DllImport("gdi32.dll")] static extern bool DeleteDC(IntPtr dc);
 [DllImport("gdi32.dll")] static extern IntPtr SelectObject(IntPtr dc,IntPtr value);
 [DllImport("gdi32.dll")] static extern bool DeleteObject(IntPtr value);
 [DllImport("gdi32.dll")] static extern bool BitBlt(IntPtr to,int x,int y,int w,int height,IntPtr from,int sx,int sy,uint mode);
 [StructLayout(LayoutKind.Sequential)] struct Info {public int size,width,height;public short planes,bits;public int compression,image,xppm,yppm;public uint used,important;}
 [DllImport("gdi32.dll")] static extern IntPtr CreateDIBSection(IntPtr dc,ref Info info,uint use,out IntPtr bits,IntPtr section,uint offset);
 public static ulong[] Frame(IntPtr h){
  const int w=400,height=300;IntPtr source=GetDC(h),memory=CreateCompatibleDC(source),bits;
  Info info=new Info{size=40,width=w,height=-height,planes=1,bits=32};IntPtr bitmap=CreateDIBSection(source,ref info,0,out bits,IntPtr.Zero,0),old=SelectObject(memory,bitmap);
  try{if(bitmap==IntPtr.Zero||!BitBlt(memory,0,0,w,height,source,160,200,0x00CC0020))throw new Exception("Frame capture failed");
   byte[] data=new byte[w*height*4];Marshal.Copy(bits,data,0,data.Length);ulong hash=1469598103934665603,ink=0;
   unchecked{for(int i=0;i<data.Length;i+=4){hash=(hash^data[i])*1099511628211;hash=(hash^data[i+1])*1099511628211;hash=(hash^data[i+2])*1099511628211;if(data[i]<80&&data[i+1]<80&&data[i+2]<80)ink++;}}return new[]{hash,ink};
  }finally{SelectObject(memory,old);DeleteObject(bitmap);DeleteDC(memory);ReleaseDC(h,source);}
 }

 public static int Stat(IntPtr h,string key){return GetPropA(h,"MathomirLayer_"+key).ToInt32()-1;}
 public static long Send(IntPtr h,uint message,int wp,IntPtr lp){UIntPtr result;if(SendMessageTimeout(h,message,(IntPtr)wp,lp,2,5000,out result)==IntPtr.Zero)throw new Exception("Control did not respond");return (long)result.ToUInt64();}
 public static long Probe(IntPtr h,int kind,int arg){return Send(h,0x8000+156,kind,(IntPtr)arg);}
 public static void Drag(IntPtr frame,IntPtr view,int x,int y,int endX,int endY){SetForegroundWindow(frame);Point a=new Point{x=x,y=y},b=new Point{x=endX,y=endY};ClientToScreen(view,ref a);ClientToScreen(view,ref b);SetCursorPos(a.x,a.y);System.Threading.Thread.Sleep(100);mouse_event(2,0,0,0,UIntPtr.Zero);System.Threading.Thread.Sleep(80);try{for(int i=1;i<=5;i++){SetCursorPos(a.x+(b.x-a.x)*i/5,a.y+(b.y-a.y)*i/5);System.Threading.Thread.Sleep(60);}}finally{mouse_event(4,0,0,0,UIntPtr.Zero);}System.Threading.Thread.Sleep(150);}
}
'@
function Check($ok,$why){if(!$ok){throw $why}}
function Capture($h,$name){$r=[MathomirUiProbe]::WindowRect($h);$b=New-Object Drawing.Bitmap ($r.Right-$r.Left),($r.Bottom-$r.Top);$g=[Drawing.Graphics]::FromImage($b);try{$g.CopyFromScreen($r.Left,$r.Top,0,0,$b.Size);$b.Save((Join-Path $folder $name))}finally{$g.Dispose();$b.Dispose()}}
function Command($id){[MathomirUiProbe]::Send($main,273,$id)|Out-Null}
function Dialog($command,$title){[MathomirUiProbe]::PostMessage($main,273,[IntPtr]$command,[IntPtr]::Zero)|Out-Null;for($i=0;$i -lt 50;$i++){Start-Sleep -Milliseconds 100;$d=[MathomirUiProbe]::Window($app.Id,$title);if($d -ne [IntPtr]::Zero){return $d}};throw "Dialog did not open: $title"}
function CloseDialog($d,$id=1){[MathomirUiProbe]::PostMessage($d,273,[IntPtr]$id,[IntPtr]::Zero)|Out-Null;for($i=0;$i -lt 40;$i++){Start-Sleep -Milliseconds 100;if(![MathomirUiProbe]::IsWindowVisible($d)){return}};throw 'Dialog did not close'}
function Panel {Command 33108;for($i=0;$i -lt 40;$i++){Start-Sleep -Milliseconds 50;$p=[MathomirUiProbe]::Child($view,33108);if($p -ne [IntPtr]::Zero -and [MathomirUiProbe]::IsWindowVisible($p)){return $p}};throw 'Canvas slider panel did not appear'}
function ClosePanel($p){[MathomirUiProbe]::Send($p,273,2)|Out-Null;Start-Sleep -Milliseconds 100;Check (![MathomirUiProbe]::IsWindowVisible($p)) 'Panel did not hide'}
function DragFrames($p,$name){
 $track=[MathomirUiProbe]::Child($p,1510);$frames=New-Object 'System.Collections.Generic.HashSet[ulong]';$worst=0;$blank=0
 foreach($position in (180..820|Where-Object {($_-180)%20 -eq 0})){
  $watch=[Diagnostics.Stopwatch]::StartNew();[InteractiveUI]::Send($track,1029,1,[IntPtr]$position)|Out-Null;[InteractiveUI]::Send($p,276,5,$track)|Out-Null;$watch.Stop();$worst=[Math]::Max($worst,$watch.ElapsedMilliseconds)
  Start-Sleep -Milliseconds 30;$frame=[InteractiveUI]::Frame($view);$frames.Add($frame[0])|Out-Null;if($frame[1] -lt 30){$blank++;Write-Output "Low ink at $name position $position : $($frame[1]) pixels"}
 }
 [InteractiveUI]::Send($p,276,8,$track)|Out-Null;Start-Sleep -Milliseconds 700
 Write-Output "Live $name drag: $($frames.Count) distinct frames; maximum input $worst ms; $blank blank frames."
 Check ($frames.Count -ge 8) "$name slider starved curve updates";Check ($worst -lt 200) "$name slider blocked the UI";Check ($blank -eq 0) "$name slider erased the visible curve"
 Check ([double][MathomirUiProbe]::Text([MathomirUiProbe]::Child($p,1511)) -eq 3.2) "$name slider dropped its final value"
}
function SaveDoc {Command 0xE103;return [xml](Get-Content $script:fixture -Raw)}
function Load($name,$xml){$script:fixture=Join-Path $folder ("interactive-$name.mom");$xml|Set-Content $fixture -Encoding ascii;[MathomirUiProbe]::OpenFile($main,$fixture);Start-Sleep -Milliseconds 350;[MathomirUiProbe]::Send($view,273,32775)|Out-Null;[MathomirUiProbe]::Send($view,276,4)|Out-Null;for($i=0;$i -lt 10;$i++){[MathomirUiProbe]::Send($view,277,2)|Out-Null}}
function Reopen($name){$copy=Join-Path $folder ("interactive-$name.mom");Copy-Item $fixture $copy;[MathomirUiProbe]::OpenFile($main,$copy);$script:fixture=$copy;Start-Sleep -Milliseconds 400}
function PickObjects($mask){[InteractiveUI]::Probe($view,8,$mask)|Out-Null}
function SetField($dialog,$id,$text){[MathomirUiProbe]::SetText([MathomirUiProbe]::Child($dialog,$id),[string]$text)}
function Place($x=100,$y=100){[MathomirUiProbe]::Mouse($view,512,0,$x,$y);[MathomirUiProbe]::Mouse($view,513,1,$x,$y);[MathomirUiProbe]::Mouse($view,514,0,$x,$y);[MathomirUiProbe]::Send($view,258,27)|Out-Null;[MathomirUiProbe]::Mouse($view,512,0,850,40);Start-Sleep -Milliseconds 800}
function Slider($d,$id,$position){$s=[MathomirUiProbe]::Child($d,$id);[InteractiveUI]::Send($s,1029,1,[IntPtr]$position)|Out-Null;[InteractiveUI]::Send($d,276,5,$s)|Out-Null;Start-Sleep -Milliseconds 450;[InteractiveUI]::Send($d,276,8,$s)|Out-Null;Start-Sleep -Milliseconds 250}
function Black($x,$y,$w,$h){return [MathomirUiProbe]::CountColor($view,$x,$y,$w,$h,0)}
function HoverRoot($doc,$i){$o=$doc.mathomir.ChildNodes[$i];$type=if($o.HasAttribute('type')){[int]$o.type}else{[int]$o.t};$x=[int]$o.X+$(if($type -eq 2){20}else{5});$y=[int]$o.Y-$(if($type -eq 1){5}else{0});[MathomirUiProbe]::Mouse($view,512,0,$x,$y);$target=[InteractiveUI]::Probe($view,4,0);Check ($target -eq $i+1) "Wrong object hovered: $target instead of $($i+1)";return @([InteractiveUI]::Stat($view,'Left'),[InteractiveUI]::Stat($view,'Top'),[InteractiveUI]::Stat($view,'Right'),[InteractiveUI]::Stat($view,'Bottom'))}
function MoveRoot($doc,$i,$dx,$dy){$r=HoverRoot $doc $i;$x=[InteractiveUI]::Stat($view,'CenterX');$y=[InteractiveUI]::Stat($view,'CenterY');Check ($x -ge 0) 'Connected object has no middle grip';[InteractiveUI]::Drag($main,$view,$x,$y,($x+$dx),($y+$dy));return SaveDoc}
function OnEdge($point,$r){return $point.x -ge $r[0]-2 -and $point.x -le $r[2]+2 -and $point.y -ge $r[1]-2 -and $point.y -le $r[3]+2 -and [Math]::Min([Math]::Min([Math]::Abs($point.x-$r[0]),[Math]::Abs($point.x-$r[2])),[Math]::Min([Math]::Abs($point.y-$r[1]),[Math]::Abs($point.y-$r[3]))) -le 3}
function Attached($doc,$source=0,$target=1,$connector=2){$line=$doc.mathomir.ChildNodes[$connector];$points=@(ShaderPoints $line);$a=HoverRoot $doc $source;$b=HoverRoot $doc $target;Check (OnEdge $points[0] $a) 'Connector source is detached';Check (OnEdge $points[1] $b) 'Connector target is detached';return $points}
$exe=(Resolve-Path source/build/Mathomir.exe).Path;$folder=Split-Path $exe
$env:MATHOMIR_PLACEMENT_DIAGNOSTICS='1';$env:MATHOMIR_DIAGNOSTIC_STARTUP='1'
$app=Start-Process $exe -WorkingDirectory $folder -PassThru
try{
 Start-Sleep -Seconds 2;$app.Refresh();$main=$app.MainWindowHandle;Check ($main -ne [IntPtr]::Zero) 'App did not start';[InteractiveUI]::ShowWindow($main,3)|Out-Null;$view=[MathomirUiProbe]::Child($main,0xE900)
 # Embedded panel: page remains enabled, native controls render live, each drag is one Undo.
