 [MathomirUiProbe]::Send($d,273,1504)|Out-Null;Check ([MathomirUiProbe]::IsWindowVisible([MathomirUiProbe]::Child($d,1514))) 'Ranges did not expand inline';SetField $d 1514 0;[MathomirUiProbe]::Send($d,273,1501)|Out-Null;Check ([MathomirUiProbe]::Text([MathomirUiProbe]::Child($d,1505)).Contains('minimum')) 'Invalid step accepted';SetField $d 1514 .1;Slider $d 1510 800;Capture $main 'interactive-slider-ranges.png';[MathomirUiProbe]::Send($d,273,1504)|Out-Null
 DragFrames $d 'explicit';$s=SaveDoc;Check ([double]$s.SelectSingleNode('//sliders').a -eq 3.2) 'Drag final value was dropped';Command 0xE12B;$s=SaveDoc;Check ([double]$s.SelectSingleNode('//sliders').a -eq 3) 'A drag made more than one Undo entry'
 # Leave the panel open while typing and moving a different object on the page.
 [MathomirUiProbe]::Mouse($view,512,0,730,500);[MathomirUiProbe]::Mouse($view,513,1,730,500);[MathomirUiProbe]::Mouse($view,514,0,730,500);foreach($letter in 'TARGET'.ToCharArray()){[MathomirUiProbe]::Send($view,258,[int]$letter)|Out-Null};[MathomirUiProbe]::Send($view,258,27)|Out-Null;$s=SaveDoc;Check ($s.mathomir.ChildNodes.Count -eq 2) 'Canvas typing was blocked by the panel';$s=MoveRoot $s 1 20 10;Check ([MathomirUiProbe]::IsWindowVisible($d)) 'Canvas editing hid the panel'
