 [InteractiveUI]::ShowWindow($main,9)|Out-Null;[InteractiveUI]::MoveWindow($main,20,20,1050,760,$true)|Out-Null;Start-Sleep -Milliseconds 200;$pr=[MathomirUiProbe]::WindowRect($d);$vr=[MathomirUiProbe]::WindowRect($view);Check ($pr.Left -ge $vr.Left -and $pr.Right -le $vr.Right) 'Resizing left the panel outside the page';[InteractiveUI]::ShowWindow($main,3)|Out-Null;Start-Sleep -Milliseconds 200
