 PickObjects 2;Command 32811;$deleted=SaveDoc;Check ($deleted.mathomir.ChildNodes.Count -eq 2 -and $deleted.SelectNodes('//connector').Count -eq 1) 'Target deletion damaged the connector';Command 0xE12B;$s=SaveDoc;Attached $s|Out-Null;Reopen 'connector-reopened';$s=SaveDoc;$s=MoveRoot $s 0 25 -15;Attached $s|Out-Null;Capture $main 'interactive-connector-follow.png'
 PickObjects 7;Check ([InteractiveUI]::Probe($view,2,0) -eq 1) 'Connected diagram copy failed';Place 100 400;$s=SaveDoc;Check ($s.mathomir.ChildNodes.Count -eq 6 -and $s.SelectNodes('//connector').Count -eq 2) 'Connected diagram paste failed';$links=$s.SelectNodes('//connector');Check ($links[0].from -ne $links[1].from -and $links[0].to -ne $links[1].to) 'Copied connector still points to the original objects';$oldLine=$s.mathomir.ChildNodes[2].OuterXml;$s=MoveRoot $s 3 25 -20;Check ($s.mathomir.ChildNodes[2].OuterXml -eq $oldLine) 'Moving copied content changed the original connector';Attached $s 3 4 5|Out-Null
 PickObjects 4;[InteractiveUI]::Probe($view,2,0)|Out-Null;Place 250 100;$s=SaveDoc;Check (!$s.mathomir.ChildNodes[6].SelectSingleNode('./connector')) 'A lone copied connector silently attached to original objects';Capture $main 'interactive-connector-copy.png'
 # The Windows clipboard uses a separate import path from click-to-copy.
 PickObjects 7;Command 0xE122;[MathomirUiProbe]::Mouse($view,512,0,100,100);Command 0xE125;Place 120 120;$os=SaveDoc;Check ($os.mathomir.ChildNodes.Count -eq 10 -and $os.SelectNodes('//connector').Count -eq 3) 'Windows clipboard diagram paste failed';$last=$os.SelectNodes('//connector')[2];$other=$os.SelectNodes('//connector')[0];Check ($last.from -ne $other.from -and $last.to -ne $other.to) 'Ctrl+C/Ctrl+V kept original object references'
 # Cut/paste moves an existing target identity, keeping its original connection.
 $cutXml='<?xml version="1.0"?><mathomir><obj type="2" X="150" Y="180"><dw d="32|0,0;3200,0;3200,1920;0,1920;0,0"/></obj><obj type="2" X="500" Y="300"><dw d="32|0,0;3200,0;3200,1920;0,1920;0,0"/></obj></mathomir>';Load 'connector-cut' $cutXml;PickObjects 3;$d=Dialog 33115 'Attached connector';CloseDialog $d;$s=SaveDoc;$targetId=$s.SelectSingleNode('//connector').to;PickObjects 2;Command 0xE123;$cut=SaveDoc;Check ($cut.mathomir.ChildNodes.Count -eq 2) 'Cut did not remove the target';[MathomirUiProbe]::Mouse($view,512,0,500,280);Command 0xE125;Place 520 290;$cut=SaveDoc;Check ($cut.mathomir.ChildNodes.Count -eq 3 -and $cut.SelectSingleNode('//connector').to -eq $targetId) 'Cut/paste lost the existing target reference';Check ($cut.mathomir.ChildNodes[2].SelectSingleNode('./objectinfo').oid -eq $targetId) 'Cut/paste replaced the target identity';Attached $cut 0 2 1|Out-Null
 # A text target follows the same object-reference path.
 $xml='<?xml version="1.0"?><mathomir><obj type="2" X="150" Y="180"><dw d="32|0,0;3200,0;3200,1920;0,1920;0,0"/></obj><obj type="1" X="500" Y="330"><ex stxt="1"><var t="TARGET" f="00"/></ex></obj></mathomir>';Load 'connector-text' $xml;PickObjects 3;$d=Dialog 33115 'Attached connector';CloseDialog $d;$s=SaveDoc;$s=MoveRoot $s 1 30 15;Attached $s|Out-Null;Capture $main 'interactive-connector-text.png'
 Write-Output 'Connectors passed: native dialog, movement, target resize, Undo, deletion recovery, save/reopen, independent diagram copy, lone-connector copy and text targets.'
}catch{if($main -ne [IntPtr]::Zero){Capture $main 'interactive-failure.png'};throw}finally{if($app -and !$app.HasExited){Stop-Process -Id $app.Id -Force};Remove-Item Env:MATHOMIR_PLACEMENT_DIAGNOSTICS -ErrorAction SilentlyContinue;Remove-Item Env:MATHOMIR_DIAGNOSTIC_STARTUP -ErrorAction SilentlyContinue}
